const ELEMENT_PROP_KEYS = new Set(["theme","value","suffix","label","pushGap","stagger","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  value: "1000",
  suffix: "×",
  label: "fewer keyframes to set by hand",
  pushGap: 15,
  stagger: 4,
  accent: "#3B5BFD",
  fontFamily: "Schibsted Grotesk",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type MagnitudePushElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof MagnitudePushBase>;

const MagnitudePushInner = forwardRef<
  HTMLDivElement,
  MagnitudePushElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<MagnitudePush>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <MagnitudePushBase
          {...(componentProps as unknown as ComponentProps<typeof MagnitudePushBase>)}
        />
      </div>
    </Sequence>
  );
});

export const MagnitudePush = Interactive.withSchema({
  Component: MagnitudePushInner,
  componentName: "<MagnitudePush>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
